async function exportInsuranceWorkbook(){const t=trip();if(!t||(!adminAccess()&&!CoralCloud.can(t.id,'documents')))return;const snapshot=structuredClone(t);try{await loadExcelLibrary();XLSX.writeFile(CoralExport.insuranceWorkbook(snapshot,XLSX,C),'DATOS para el SEGURO y Manifiesto - '+snapshot.name.replace(/[\\/:*?"<>|]/g,'-')+'.xlsx');}catch(e){notify('No se pudo exportar: '+e.message);}}
async function exportWorkbook(){try{await loadExcelLibrary();const t=trip();XLSX.writeFile(CoralExport.workbook(t,XLSX,C),'Coral - '+t.name.replace(/[\\/:*?"<>|]/g,'-')+'.xlsx');}catch(e){notify('No se pudo exportar: '+e.message);}}
function dietaryDocument(t){
 const people=[...t.passengers].sort((a,b)=>(a.lastName+' '+a.firstName).localeCompare(b.lastName+' '+b.firstName,'es'));
 const diets=people.filter(p=>String(p.specialDiet||'').trim()&&!['comun','normal','sin restricciones','ninguna'].includes(C.norm(p.specialDiet)));
 const technical=people.filter(p=>String(p.medicationAllergies||'').trim()||String(p.medications||'').trim());
 const food=reportHeader(t,'Requerimientos alimentarios')+'<h3>Dietas especiales</h3><p>'+diets.length+' '+(diets.length===1?'persona con dieta especial informada.':'personas con dieta especial informada.')+'</p>'+(diets.length?reportTable(['Pasajero','Dieta especial','Hospedaje','Habitación'],diets.map(p=>[p.lastName+', '+p.firstName,p.specialDiet,p.hotel||'Sin asignar',p.room||'Sin asignar'])):'<p>No hay dietas especiales registradas para esta salida.</p>');
 return food+'<section class="dietary-technical"><h3>Detalles técnicos informados</h3>'+(technical.length?reportTable(['Pasajero','Alergias a medicamentos','Medicación que toma','Observaciones'],technical.map(p=>[p.lastName+', '+p.firstName,p.medicationAllergies||'No informado',p.medications||'No informado',p.notes||''])):'<p>No hay alergias a medicamentos ni medicación registradas.</p>')+'</section>';
}
function boardingHeader(t){return '<div class="boarding-heading"><div><small>CORAL · GESTIÓN DE SALIDAS</small><h1>Lista de embarque</h1><h2>'+esc(t.name)+'</h2><div class="boarding-dates"><span>Salida: '+esc(dateText(t.departure))+'<br>Regreso: '+esc(dateText(t.returnDate))+'</span><span>Check in: '+esc(dateText(t.checkIn))+'<br>Check out: '+esc(dateText(t.checkOut))+'</span></div></div><img src="assets/coral-byn.svg" alt="Brasil Coral"></div>';}
function boardingDocument(t){
 const people=[...t.passengers].sort((a,b)=>(a.lastName+' '+a.firstName).localeCompare(b.lastName+' '+b.firstName,'es'));
 const pages=Math.max(1,Math.ceil(people.length/60));
 return Array.from({length:pages},(_,page)=>'<section class="manifest-page boarding-paper">'+boardingHeader(t)+'<p class="boarding-paper-note">Menores: cotejar partida de nacimiento y autorización de viaje, según corresponda. Prioridades orientativas, sin asignación de butaca.</p><table><colgroup>'+[4,28,14,7,12,25,10].map(w=>'<col style="width:'+w+'%">').join('')+'</colgroup><thead><tr>'+['N.º','Apellido y nombre','Documento','Ejemplar','Edad / menor','Prioridad de butaca','Ingresó'].map(h=>'<th>'+h+'</th>').join('')+'</tr></thead><tbody>'+people.slice(page*60,(page+1)*60).map((p,i)=>{const age=C.age(p.birthDate,t.departure);return '<tr><td>'+(page*60+i+1)+'</td><td>'+esc(p.lastName+', '+p.firstName)+'</td><td>'+esc(p.documentType+' '+p.document)+'</td><td class="paper-exemplar">'+esc(p.dniCopy||'—')+'</td><td class="'+(age!==''&&age<18?'paper-minor':'')+'">'+(age===''?'Sin fecha':age<18?'MENOR · '+age:age+' años')+'</td><td>'+esc(p.seatPriority||'')+'</td><td class="paper-check"><span></span></td></tr>';}).join('')+'</tbody></table><div class="manifest-totals"><span>'+people.length+' personas · Casillas libres para control en papel</span><span>Hoja '+(page+1)+' de '+pages+'</span></div></section>').join('');
}

function manifestHeader(t){return '<h1>MANIFIESTO DE PASAJEROS</h1><div class="manifest-header">'+reportTable(['Paso fronterizo','Autoridad migratoria','Ruta / Itinerario','Fecha salida','Regreso'],[[t.border,t.migrationAuthority,t.route,t.departure?dateText(t.departure):'',t.returnDate?dateText(t.returnDate):'']])+reportTable(['Consignado a','Empresa de transporte','Unidad / N.º interno','Dominio'],[[t.consignee,t.carrier,t.unit,t.plate]])+'</div>';}
function manifestDni(p){const raw=String(p.document||'');const digits=raw.replace(/[.\s-]/g,'');return p.documentType==='DNI'&&/^\d{1,7}$/.test(digits)?'M'+digits:raw;}
function manifestRoster(people,slots,offset=0){const rows=Array.from({length:Math.max(slots,people.length)},(_,i)=>{const p=people[i];return '<tr><td>'+(offset+i+1)+'</td>'+[p?.lastName||'',p?.firstName||'',p?((p.documentType||'')+' '+manifestDni(p)):'',p?.birthDate?dateText(p.birthDate):'',p?.sex||'',p?.nationality||''].map(v=>'<td>'+esc(v)+'</td>').join('')+'</tr>';}).join('');return '<table class="manifest-roster"><colgroup>'+[4,21,22,22,13,4,14].map(w=>'<col style="width:'+w+'%">').join('')+'</colgroup><thead><tr>'+['N.º','Apellido','Nombre','Documento','Fecha Nac.','Sx','Nac.'].map(v=>'<th>'+esc(v)+'</th>').join('')+'</tr></thead><tbody>'+rows+'</tbody></table>';}
function manifestDocument(t){const crew=[...(t.drivers||[]),...t.passengers.filter(p=>p.role==='Tripulante')],people=t.passengers.filter(p=>p.role!=='Tripulante');const pages=Math.max(1,Math.ceil(people.length/60));return Array.from({length:pages},(_,i)=>'<section class="manifest-page">'+manifestHeader(t)+'<h2>TRIPULANTES / CONDUCTORES</h2>'+manifestRoster(crew,2)+'<h2>PASAJEROS</h2>'+manifestRoster(people.slice(i*60,(i+1)*60),60,i*60)+'<div class="manifest-totals"><strong>Pasajeros: '+people.length+' · Tripulantes: '+crew.length+' · Total: '+(people.length+crew.length)+'</strong><span>Hoja '+(i+1)+' de '+pages+'</span></div><div class="manifest-stamps">Espacio libre para sellos / observaciones</div></section>').join('');}
function reportHTML(t,type,filter=''){let people=t.passengers;const head=reportHeader(t,reportNames[type]);if(type==='dietary')return dietaryDocument(t);if(type==='insurance')return head+reportTable(['Nombre','Apellido','Nacimiento','Sexo','Tipo doc.','Documento','Nacionalidad'],people.map(p=>[p.firstName,p.lastName,dateText(p.birthDate),p.sex,p.documentType,p.document,p.nationality]));if(type==='manifest')return manifestDocument(t);if(type==='boarding')return boardingDocument(t);if(type==='rooming'){const hotels=[...new Set(people.map(p=>p.hotel).filter(Boolean))].sort().filter(h=>!filter||h===filter);return hotels.length?hotels.map(h=>`<section class="report-section">${reportHeader(t,'Rooming · '+h)}${roomTable(t,people.filter(p=>p.hotel===h).sort((a,b)=>(a.groupId+a.room).localeCompare(b.groupId+b.room)))}</section>`).join(''):head+'<p>No hay alojamientos asignados.</p>';}
if(type==='vouchers'){const groups=t.groups.filter(g=>!filter||g.id===filter);return groups.length?groups.map(g=>{const ps=people.filter(p=>p.groupId===g.id);return `<section class="report-section">${reportHeader(t,'Voucher · '+g.name)}<p><strong>Reserva:</strong> ${esc(g.name)} · ${ps.length} personas</p>${reportTable(['Pasajero','Documento','Butaca'],ps.map(p=>[fullName(p),p.document,p.noSeat?'Sin butaca':seatLabel(t,p.seatId)]))}<h3 style="margin-top:25px">Servicios registrados</h3>${reportTable(['Pasajero','Hospedaje','Habitación','Régimen'],ps.map(p=>[fullName(p),p.hotel,p.roomType+(p.room?' · '+p.room:''),p.meal]))}<p><strong>Presentación:</strong> ${esc(t.presentation)} · ${esc(t.boardingPlace)}</p><p><strong>Coordinación:</strong> ${esc(t.coordinator)}</p>${ps.filter(p=>p.notes).map(p=>`<p>${esc(fullName(p))}: ${esc(p.notes)}</p>`).join('')}</section>`;}).join(''):head+'<p>No hay grupos creados.</p>';}
return '';}
function reportToolbar(){return `<div class="document-toolbar" aria-label="Controles del documento"><div class="zoom-controls"><button type="button" class="tertiary icon-button" data-action="zoom-out" aria-label="Alejar documento">−</button><span id="zoom-value" aria-live="polite">${Math.round(reportZoom*100)}%</span><button type="button" class="tertiary icon-button" data-action="zoom-in" aria-label="Acercar documento">+</button><span class="toolbar-divider" aria-hidden="true"></span><button type="button" class="tertiary" data-action="zoom-fit">Ajustar al ancho</button></div><div class="toolbar-actions">${button('Volver','goto-documents','tertiary')}${button('Imprimir','print','secondary')}${button('Guardar PDF','print','primary')}</div></div>`;}
function applyReportZoom(value){reportZoom=Math.max(.7,Math.min(1.5,value));const content=$('.document-preview-content'),label=$('#zoom-value');if(content)content.style.setProperty('--document-zoom',reportZoom);if(label)label.textContent=Math.round(reportZoom*100)+'%';}
function fitReportWidth(){const viewport=$('.document-canvas'),sheet=$('.document-preview-content .manifest-page')||$('.document-preview-content');if(!viewport||!sheet)return;const style=getComputedStyle(viewport),available=viewport.clientWidth-parseFloat(style.paddingLeft)-parseFloat(style.paddingRight)-12,natural=sheet.getBoundingClientRect().width/reportZoom;applyReportZoom(Math.min(1.5,available/natural));}
function showReport(type,filter=''){
 if(!adminAccess()&&!CoralCloud.can(activeId,'documents'))return;
 reportType=type;reportFilter=filter;reportZoom=1;const t=trip();let opts=[];
 if(type==='rooming')opts=[...new Set(t.passengers.map(p=>p.hotel).filter(Boolean))].map(h=>[h,h]);if(type==='vouchers')opts=t.groups.map(g=>[g.id,g.name]);
 const missing=type==='dietary'?0:(type==='manifest'?C.manifestPeople(t):t.passengers).filter(p=>!p.document).length;
 $('#main').classList.add('document-view');
 $('#main').innerHTML=pageTitle('DOCUMENTO',reportNames[type],`${t.passengers.length} pasajeros · ${t.name} · Salida ${shortDate(t.departure)}`,'')+((type==='rooming'||type==='vouchers')?`<div class="report-select">${selectField(type==='rooming'?'Alojamiento':'Grupo','reportFilter',[['','Todos'],...opts],filter)}</div>`:'')+(missing?`<div class="notice warning">Hay ${missing} personas sin documento. Revisá los datos antes de entregar el archivo.</div>`:'')+(type==='rooming'&&t.passengers.some(p=>!p.hotel)?'<div class="notice warning">Los pasajeros sin hospedaje asignado no aparecen en el rooming.</div>':'')+(type==='vouchers'&&t.passengers.some(p=>!p.groupId)?'<div class="notice warning">Los pasajeros sin grupo no tienen voucher. Asignales un grupo para incluirlos.</div>':'')+`<section class="document-viewer">${reportToolbar()}<div class="document-canvas"><div class="document-preview-content" style="--document-zoom:${reportZoom}">${reportHTML(t,type,filter)}</div></div></section>`;
 const select=$('[name=reportFilter]');if(select)select.onchange=e=>showReport(type,e.target.value);
 requestAnimationFrame(()=>fitReportWidth());
}
function download(name,text,type){const blob=new Blob([text],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
