document.addEventListener('click',e=>{const b=e.target.closest('[data-action],[data-view]');if(!b||b.disabled)return;if(!adminAccess()&&b.dataset.view&&!CoralCloud.can(activeId,b.dataset.view))return;if(!adminAccess()&&b.dataset.action&&!['open-boarding','report','print','close','goto-documents','zoom-in','zoom-out','zoom-fit','insurance-excel'].includes(b.dataset.action))return;if(b.dataset.view==='boarding'){location.href='embarque.html?salida='+encodeURIComponent(activeId);return;}if(b.dataset.view){view=b.dataset.view;query='';moving='';render();return;}const a=b.dataset.action,id=b.dataset.id,t=trip();if(a==='close'){closeModal();return;}if(a==='new'){newTrip();return;}if(a==='restore'){$('#restore-file').click();return;}if(a==='backup'){backup();return;}if(a==='demo'){demo();return;}if(storageBlocked){notify('Restaurá un respaldo para continuar.');return;}switch(a){case'insurance-excel':exportInsuranceWorkbook();break;case'open-boarding':location.href='embarque.html?salida='+encodeURIComponent(activeId);break;case'access-new':editAccess();break;case'access-edit':editAccess(b.dataset.email);break;case'access-revoke':confirmAction('Revocar acceso','Este correo dejará de acceder a sus salidas.',async()=>{try{await CoralCloud.revokeAccess(b.dataset.email);render();notify('Acceso revocado.');}catch(e){notify(e.message);}});break;case'delete-trip':deleteTrip(id);break;case'excel-export':exportWorkbook();break;case'bus-legal':editBusLegal();break;case'bus-details':editImportedBus();break;case'room-new':editRoom('',b.dataset.hotel);break;case'room-edit':editRoom(id);break;case'room-delete':confirmAction('Eliminar habitación','Los huéspedes quedarán sin habitación y disponibles para asignarlos a otra.',()=>mutate(()=>C.deleteRoom(t,id)));break;case'renaper-batch':prepareRenaperBatch();break;case'driver-new':editDriver();break;case'driver-edit':editDriver(id);break;case'driver-delete':confirmAction('Eliminar chofer','Se quitará este chofer del manifiesto de la salida.',()=>mutate(()=>{t.drivers=t.drivers.filter(d=>d.id!==id);}));break;case'renaper':queryRenaper(t.id,id);break;case'goto-bus':view='bus';render();break;case'goto-documents':view='documents';render();break;case'trip-edit':editTrip();break;case'open-trip':activeId=id;view='overview';floorIndex=0;render();break;case'clone-trip':{const src=data.trips.find(s=>s.id===id);promptValue('Reutilizar plano','Nombre de la nueva salida',src.name+' · Nueva salida',name=>{const nt=C.blankTrip();nt.name=name;nt.origin=src.origin;nt.destination=src.destination;nt.floors=structuredClone(src.floors);if(src.layoutMode==='list'){nt.layoutMode='list';nt.capacity=src.capacity;nt.vehicle=src.vehicle;nt.configured=true;}nt.floors.forEach(f=>{f.id=C.uid();f.seats.forEach(s=>s.id=C.uid());(f.fixtures||[]).forEach(s=>s.id=C.uid());});data.trips.push(nt);activeId=nt.id;floorIndex=0;view='bus';});break;}case'floor':floorIndex=Number(b.dataset.index);render();break;case'tool':tool=b.dataset.tool;moving='';render();break;case'seat':handleSeat(id);break;case'fixture':handleFixture(id);break;case'space':handleSpace(Number(b.dataset.row),Number(b.dataset.col));break;case'add-row':mutate(()=>{if(t.floors[floorIndex].rows>=40)throw Error('Máximo 40 filas por piso.');t.floors[floorIndex].rows++;});break;case'remove-row':mutate(()=>{const f=t.floors[floorIndex];if(f.rows<=1||[...f.seats,...(f.fixtures||[])].some(s=>s.row===f.rows-1))throw Error('La última fila debe estar vacía.');f.rows--;});break;case'floor-name':promptValue('Nombre del piso','Nombre',t.floors[floorIndex].name,name=>{if(!name)throw Error('Completá el nombre.');t.floors[floorIndex].name=name;});break;case'confirm-layout':mutate(()=>{C.validateTrip(t);t.configured=true;moving='';});break;case'unlock-layout':mutate(()=>{t.configured=false;tool='add';moving='';});break;case'passenger-new':editPassenger();break;case'passenger-seat':editPassenger('',id);break;case'passenger-edit':editPassenger(id);break;case'passenger-delete':confirmAction('Eliminar pasajero','Se eliminará su ficha y se liberará su butaca. Los demás pasajeros se conservarán.',()=>mutate(()=>{t.passengers=t.passengers.filter(p=>p.id!==id);}));break;case'assign-seat':{const free=t.passengers.filter(p=>!p.seatId&&!p.noSeat);if(!free.length){notify('No hay pasajeros pendientes de asignación.');break;}modal('Asignar butaca '+seatLabel(t,id),`<form id="assign-form">${selectField('Pasajero','passenger',free.map(p=>[p.id,fullName(p)]))}<div class="modal-actions">${button('Cancelar','close')}<button class="primary">Asignar</button></div></form>`);$('#assign-form').onsubmit=e=>{e.preventDefault();mutate(()=>{const p=t.passengers.find(p=>p.id===new FormData(e.target).get('passenger'));C.savePassenger(t,{...p,seatId:id});closeModal();});};break;}case'group-new':editGroup();break;case'group-edit':editGroup(id);break;case'group-delete':confirmAction('Eliminar grupo','Los pasajeros se conservarán y quedarán sin grupo.',()=>mutate(()=>{t.groups=t.groups.filter(g=>g.id!==id);t.passengers.forEach(p=>{if(p.groupId===id)p.groupId='';});}));break;case'board':board(id);break;case'group-board':confirmAction('Embarcar grupo','Se marcarán como embarcados todos los integrantes de este grupo.',()=>mutate(()=>{t.passengers.forEach(p=>{if(p.groupId===id)p.boarded=true;});}));break;case'csv':exportCSV();break;case'report':showReport(b.dataset.type);break;case'rooming-report':view='documents';render();showReport('rooming');break;case'print':$('#print-area').innerHTML=reportHTML(t,reportType,reportFilter);document.title=reportNames[reportType]+' - '+t.name;window.print();document.title='Coral · Salidas';break;}});
$('#new-trip').onclick=newTrip;$('#backup').onclick=backup;$('#restore').onclick=()=>$('#restore-file').click();$('#trip-select').onchange=e=>{const preview=view==='documents'&&!!$('.document-viewer');activeId=e.target.value;floorIndex=0;moving='';query='';reportFilter='';render();if(preview)showReport(reportType);};
$('#restore-file').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{if(file.size>10*1024*1024)throw Error('El archivo supera el límite de 10 MB.');const incoming=C.validateStore(JSON.parse(await file.text()));confirmAction('Restaurar respaldo',`Se cargarán ${incoming.trips.length} salidas y se reemplazará el guardado actual. Descargá un respaldo antes si necesitás conservarlo.`,()=>mutate(()=>{data=incoming;activeId=data.trips[0]?.id||'';floorIndex=0;view='overview';}));}catch(err){notify('No se pudo importar: '+err.message);}};
window.addEventListener('coral-cloud-update',()=>{if(saving)return;if($('#modal').open){remotePending=true;notify('Hay cambios nuevos en otro equipo. Cerrá este formulario para cargarlos.');return;}cloudBase=CoralCloud.snapshot();data=structuredClone(cloudBase.data);if(!data.trips.some(t=>t.id===activeId))activeId=data.trips[0]?.id||'';render();markSynced();});
render();

