try{if(adminAccess()&&CoralCloud.mode!=='local'&&localStorage.getItem(KEY)){
 const migrate=document.createElement('button');migrate.className='secondary full';migrate.textContent='Importar datos de este equipo';$('#backup').before(migrate);
 migrate.onclick=()=>{try{const legacy=C.validateStore(JSON.parse(localStorage.getItem(KEY)));confirmAction('Importar datos locales',`Se guardarán ${legacy.trips.length} salidas de este navegador en Firebase. Si una salida ya existe, se reemplazará. Las demás salidas en la nube se conservarán.`,()=>mutate(()=>{const merged=new Map(data.trips.map(t=>[t.id,t]));legacy.trips.forEach(t=>merged.set(t.id,t));data={version:1,trips:[...merged.values()]};activeId=data.trips[0]?.id||'';}));}catch(e){notify('No se pudo importar: '+e.message);}};
}}catch{}

let autoRenaper=localStorage.getItem('coral-renaper-auto')==='true';
const requests=new Map();
function renderImportedBus(t){$('#main').innerHTML=pageTitle('COLECTIVO IMPORTADO',t.vehicle||'Colectivo','Carga por capacidad, sin plano ni distribución física.',button('Editar colectivo','bus-details')+button('+ Pasajero','passenger-new','primary'))+stats(t)+busLegalCard(t)+`<section class="card"><h2>Lista de ${t.capacity} lugares</h2><p>No se asignaron números de butaca a partir del número de fila del Excel. Podés cargar pasajeros y tomar lista sin diseñar un plano.</p>${passengerTable(t,t.passengers)}</section>`;}
let excelLibrary;
function loadExcelLibrary(){if(window.XLSX)return Promise.resolve();if(!excelLibrary)excelLibrary=new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='vendor/xlsx.full.min.js';s.onload=resolve;s.onerror=()=>{excelLibrary=null;s.remove();reject(Error('No se pudo cargar el lector de Excel. Reintentá.'));};document.head.append(s);});return excelLibrary;}
function excelDialog(){
 const input=document.createElement('input');input.type='file';input.accept='.xlsx';
 input.onchange=async()=>{const file=input.files[0];if(!file)return;try{
  if(file.size>10*1024*1024)throw Error('El archivo supera los 10 MB.');
  await loadExcelLibrary();const preview=CoralExcel.read(await file.arrayBuffer(),XLSX);
  const modern=preview.format==='third-edition';
  const fields=modern?[['firstName','Nombre'],['lastName','Apellido'],['document','DNI'],['sex','Sexo'],['birthDate','Nacimiento'],['nationality','Nacionalidad'],['specialDiet','Dieta'],['notes','Observaciones'],['medicationAllergies','Alergias a medicamentos'],['medications','Medicación que toma'],['seatPriority','Prioridad de butaca']]:[['firstName','Nombre'],['lastName','Apellido'],['birthDate','Nacimiento'],['sex','Sexo'],['boarding','Embarque'],['specialDiet','Dieta especial']];
  modal('Revisar importación de Excel','<p>Primera hoja: <strong>'+esc(preview.sheet)+'</strong> · '+preview.passengers.length+' pasajeros · '+(modern?'Plantilla tercera edición':'Plantilla anterior')+'</p><p>'+ (modern?'Nombre de la salida en A1 y fecha en B2. Las columnas se identifican por sus encabezados en la fila 4. Completá la capacidad real antes de crear la salida.':'Fecha en A1, año en B1 y capacidad en E1. Dieta en H y Sexo en I.')+'</p><p>Revisar este archivo no guarda datos. La salida se creará únicamente al confirmar, sin plano ni ingresos marcados.</p>'+ (preview.errors.length?'<div class="notice warning">'+preview.errors.map(esc).join('<br>')+'</div>':'')+'<form id="excel-form"><div class="form-grid">'+field('Nombre / alias de la salida','name',preview.name||preview.sheet,'text','required maxlength="100"')+field('Fecha de salida','departure',preview.departure,'date','required')+field('Capacidad real del colectivo','capacity',preview.capacity??'','number','required min="'+Math.max(1,preview.passengers.length)+'" max="100" step="1"')+field('Tipo de colectivo','vehicle',preview.vehicle||'','text','placeholder="Ej. Semicama, Mix"')+'</div><div class="table-wrap" style="max-height:300px;overflow:auto;margin-top:20px"><table><thead><tr><th>Fila</th>'+fields.map(([,label])=>'<th>'+label+'</th>').join('')+'</tr></thead><tbody>'+preview.passengers.map(p=>'<tr><td>'+p.sourceRow+'</td>'+fields.map(([key])=>'<td>'+esc(p[key])+'</td>').join('')+'</tr>').join('')+'</tbody></table></div><div class="modal-actions">'+button('Cancelar','close')+'<button class="primary" '+(preview.errors.length?'disabled':'')+'>Crear salida importada</button></div></form>');
  $('#excel-form').onsubmit=e=>{e.preventDefault();try{const form=Object.fromEntries(new FormData(e.target));const imported=CoralExcel.build(preview,form.departure,form);mutate(()=>{data.trips.push(imported);activeId=imported.id;view='passengers';floorIndex=0;closeModal();});}catch(err){notify(err.message);}};
 }catch(e){notify('No se pudo importar: '+e.message);}};input.click();
}
function renaperHelp(){if(!renaperDesktop())return;modal('Prueba automática de RENAPER',`<p>Instalá la extensión local <strong>Brasil Coral · Consulta RENAPER</strong> en Chrome o Edge: Extensiones → Modo de desarrollador → Cargar descomprimida → carpeta <strong>renaper-extension</strong> dentro del proyecto.</p><p>Luego recargá esta página. La extensión abre RENAPER, completa DNI, sexo y nacimiento y envía el formulario oficial. Cualquier verificación que solicite RENAPER se resuelve en esa página. El resultado vuelve a la columna de ejemplar.</p><p>Es una prueba experimental: si RENAPER rechaza la consulta, queda pendiente. Importar Excel no envía consultas masivas.</p><label class="check"><input id="renaper-auto" type="checkbox" ${autoRenaper?'checked':''}>Consultar al guardar una ficha con los tres datos completos</label><div class="modal-actions">${button('Cerrar','close')}</div>`);$('#renaper-auto').onchange=e=>{autoRenaper=e.target.checked;localStorage.setItem('coral-renaper-auto',String(autoRenaper));};}

let batchRun=null;
function queryRenaper(tripId,pid,fromBatch=false){
 if(!renaperDesktop())return Promise.resolve(fromBatch?{ok:false,message:'RENAPER solo está disponible en computadora.'}:false);
 if((batchRun&&!fromBatch)||requests.size||saving){notify('Hay una consulta o guardado en curso.');return Promise.resolve(fromBatch?{ok:false,message:'Hay una consulta o guardado en curso.'}:false);}
 const t=data.trips.find(t=>t.id===tripId),p=t?.passengers.find(p=>p.id===pid);if(!p)return Promise.resolve(fromBatch?{ok:false,message:'El pasajero ya no está en la salida.'}:false);
 return new Promise(resolve=>{
  try{const payload=CoralRenaper.request(p),id=C.uid();
   const done=(ok,message)=>{const r=requests.get(id);if(!r)return;clearTimeout(r.connectTimer);clearTimeout(r.resultTimer);requests.delete(id);if(message&&!fromBatch)notify(message);resolve(fromBatch?{ok,message:message||''}:ok);};
   const r={tripId,pid,fromBatch,key:CoralRenaper.fingerprint(p),done};requests.set(id,r);
   r.connectTimer=setTimeout(()=>{if(!r.accepted)done(false,'No se detectó la extensión. Abrí «Configurar RENAPER».');},5000);
   r.resultTimer=setTimeout(()=>done(false,'Consulta vencida sin resultado de RENAPER.'),150000);
   window.postMessage({source:'coral-renaper',kind:'lookup',id,payload},location.origin);notify('Consultando RENAPER…');
  }catch(e){if(!fromBatch)notify(e.message);resolve(fromBatch?{ok:false,message:e.message}:false);}
 });
}
window.addEventListener('message',async e=>{
 if(e.source!==window||e.origin!==location.origin||e.data?.source!=='coral-renaper-extension')return;
 const result=e.data,r=requests.get(result.id);if(!r||r.processing)return;
 if(result.accepted){r.accepted=true;return;}
 r.processing=true;clearTimeout(r.connectTimer);clearTimeout(r.resultTimer);
 if(result.error){r.done(false,result.error);return;}
 const value=CoralRenaper.parse(result.text);
 if(!value){r.done(false,String(result.text||'RENAPER no devolvió un ejemplar reconocible.'));if(!r.fromBatch&&!$('#modal').open)modal('Respuesta de RENAPER','<p>'+esc(result.text)+'</p>'+button('Cerrar','close'));return;}
 const t=data.trips.find(t=>t.id===r.tripId),p=t?.passengers.find(p=>p.id===r.pid);
 if(!p||CoralRenaper.fingerprint(p)!==r.key){r.done(false,'La ficha cambió durante la consulta. Volvé a consultar.');return;}
 if($('#modal').open){r.done(false,'Cerrá el formulario abierto antes de volver a consultar.');return;}
 try{const saved=await mutate(()=>{p.dniCopy=value;p.dniCheckedAt=new Date().toISOString();p.dniQueryKey=r.key;p.dniSource='RENAPER';p.renaperStatus='Consultado en RENAPER';});r.done(!!saved,saved?'Ejemplar '+value+' guardado':'No se pudo guardar el resultado. Volvé a consultar.');}catch(e){r.done(false,e.message);}
});
function prepareRenaperBatch(){
 if(!renaperDesktop())return;
 if(batchRun||requests.size){notify('Ya hay una consulta en curso.');return;}
 const t=trip(),ids=t.passengers.filter(p=>{try{CoralRenaper.request(p);return true;}catch{return false;}}).map(p=>p.id);
 if(!ids.length){notify('Completá DNI, sexo y nacimiento para poder consultar.');return;}
 confirmAction('Chequear pasajeros en RENAPER',ids.length+' pasajeros se consultarán uno por uno, incluso si ya tienen ejemplar. Se omiten '+(t.passengers.length-ids.length)+' fichas incompletas o sin DNI. Habrá 5 segundos entre consultas. Dejá Brasil Coral abierto y completá cualquier verificación en RENAPER. Los errores se registran y el chequeo continúa. Al finalizar tendrás un informe.',()=>startRenaperBatch(t.id,ids));
}
async function startRenaperBatch(tripId,ids){
 if(batchRun||requests.size)return;
 const signal={stopped:false};batchRun=signal;
 const roster=(data.trips.find(t=>t.id===tripId)?.passengers||[]).map(p=>({id:p.id,name:fullName(p)}));
 const panel=document.createElement('section');panel.className='notice';panel.setAttribute('aria-live','polite');
 const label=document.createElement('span'),stop=document.createElement('button');stop.className='secondary';stop.textContent='Detener chequeo';
 stop.onclick=()=>{signal.stopped=true;stop.disabled=true;label.textContent+=' · Deteniendo al terminar la consulta actual…';};panel.append(label,stop);$('#main').before(panel);
 try{const result=await CoralRenaperBatch.run(ids,pid=>queryRenaper(tripId,pid,true),ms=>new Promise(resolve=>setTimeout(resolve,ms)),status=>{label.textContent='RENAPER: '+status.processed+' / '+status.total+' revisados · '+status.completed+' guardados'+(status.id?' · Consultando '+fullName(data.trips.find(t=>t.id===tripId)?.passengers.find(p=>p.id===status.id)||{firstName:'pasajero',lastName:''}):' · Esperando próxima consulta')+' ';},signal);
 label.textContent=(result.stopped?'Chequeo detenido':'Chequeo terminado')+': '+result.completed+' guardados · '+result.results.filter(r=>!r.ok).length+' errores. ';
 const rows=roster.map(p=>{const r=result.results.find(r=>r.id===p.id);return [p.name,r?(r.ok?'Guardado':'Error'):ids.includes(p.id)?'Sin consultar':'Omitido',r?.message||(ids.includes(p.id)?'Detenido antes de consultar':'Faltan datos o el documento no es DNI')];}).filter(row=>row[1]!=='Guardado');
 const reportText='Informe RENAPER · Errores y pendientes · '+new Date().toLocaleString('es-AR')+'\n\n'+(rows.length?rows.map(row=>row.join(' — ')).join('\n'):'Sin errores ni pendientes.');
 const details=document.createElement('details'),summary=document.createElement('summary'),body=document.createElement('div'),exportButton=document.createElement('button'),copyButton=document.createElement('button');summary.textContent='Informe de errores y pendientes';details.open=true;body.innerHTML=rows.length?reportTable(['Pasajero','Estado','Detalle'],rows,()=> 'status-alert'):'<p>Sin errores ni pendientes.</p>';exportButton.className='secondary';exportButton.textContent='Descargar informe';exportButton.onclick=()=>download('informe-renaper.txt',reportText,'text/plain;charset=utf-8');copyButton.className='secondary';copyButton.textContent='Copiar informe';copyButton.onclick=async()=>{try{await navigator.clipboard.writeText(reportText);notify('Informe copiado.');}catch{notify('No se pudo copiar. Podés seleccionar el texto del informe o descargarlo.');}};details.append(summary,body,copyButton,exportButton);panel.append(details);
 }catch(e){label.textContent='Chequeo detenido: '+e.message;}finally{batchRun=null;stop.disabled=false;stop.textContent='Cerrar';stop.onclick=()=>panel.remove();}
}
const excelButton=document.createElement('button');excelButton.hidden=!adminAccess();excelButton.className='secondary';excelButton.textContent='Importar Excel';excelButton.onclick=excelDialog;$('#new-trip').before(excelButton);
if(adminAccess()&&renaperDesktop()){const setup=document.createElement('button');setup.className='text-button full renaper-setup';setup.textContent='Configurar RENAPER';setup.onclick=renaperHelp;$('#restore').after(setup);}


function renderDrivers(t){
 const drivers=t.drivers||[];
 $('#main').innerHTML=pageTitle('TRIPULACIÓN','Choferes','Hasta dos choferes por salida. Se incluyen en el manifiesto y no ocupan butacas.',button('+ Agregar chofer','driver-new','primary',drivers.length>=2?'disabled':''))+`<section class="card"><div class="card-header"><h2>Choferes de esta salida</h2><span class="chip">${drivers.length} / 2</span></div>${drivers.length?`<div class="table-wrap"><table><thead><tr><th>Nombre y apellido</th><th>Documento</th><th>Teléfono</th><th></th></tr></thead><tbody>${drivers.map(d=>`<tr><td>${esc(fullName(d))}</td><td>${esc(d.documentType)} ${esc(d.document||'Pendiente')}</td><td>${esc(d.phone||'—')}</td><td>${button('Editar','driver-edit','secondary',`data-id="${esc(d.id)}"`)}</td></tr>`).join('')}</tbody></table></div>`:'<p>Todavía no hay choferes cargados.</p>'}</section>`;
}
function editDriver(id=''){
 const t=trip();if(!id&&(t.drivers||[]).length>=2){notify('Se permiten hasta dos choferes por salida.');return;}
 const d=id?t.drivers.find(d=>d.id===id):C.blankDriver();if(!d)return;
 modal(id?'Editar chofer':'Agregar chofer',`<form id="driver-form"><div class="form-grid">${field('Nombre','firstName',d.firstName,'text','required maxlength="100"')}${field('Apellido','lastName',d.lastName,'text','required maxlength="100"')}${selectField('Tipo de documento','documentType',['DNI','Pasaporte','Cédula','Otro'],d.documentType)}${field('Número de documento','document',d.document)}${field('Nacimiento','birthDate',d.birthDate,'date')}${selectField('Sexo (documento)','sex',[['','Sin informar'],'F','M','X'],d.sex)}${field('Nacionalidad','nationality',d.nationality)}${field('País de residencia','residence',d.residence)}${field('Ocupación','occupation',d.occupation)}${field('Teléfono','phone',d.phone,'tel')}</div><div class="modal-actions">${id?button('Eliminar chofer','driver-delete','danger',`data-id="${esc(id)}"`):''}${button('Cancelar','close')}<button class="primary" type="submit">Guardar chofer</button></div></form>`);
 $('#driver-form').onsubmit=async e=>{e.preventDefault();const draft={...d,...Object.fromEntries([...new FormData(e.target)].map(([k,v])=>[k,String(v).trim()]))};const saved=await mutate(()=>C.saveDriver(t,draft));if(saved)closeModal();};
}

function editImportedBus(){const t=trip();if(t.layoutMode!=='list')return;const occupied=t.passengers.filter(p=>!p.noSeat).length;
 modal('Editar colectivo','<form id="bus-details-form"><div class="form-grid">'+field('Tipo de colectivo','vehicle',t.vehicle,'text','required maxlength="100" placeholder="Ej. Mix, semicama, cama"')+field('Cantidad de butacas','capacity',t.capacity,'number','required min="'+Math.max(1,occupied)+'" max="100" step="1"')+'</div><p>'+occupied+' lugares ocupados. Se conservan los pasajeros, ingresos, grupos y habitaciones.</p><div class="modal-actions">'+button('Cancelar','close')+'<button class="primary" type="submit">Guardar colectivo</button></div></form>');
 $('#bus-details-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);const saved=await mutate(()=>{const draft={...t,vehicle:String(f.get('vehicle')).trim(),capacity:Number(f.get('capacity'))};C.validateTrip(draft);Object.assign(t,draft);});if(saved)closeModal();};
}

function legalFields(){return [['Paso fronterizo','border'],['Autoridad migratoria','migrationAuthority'],['Ruta','route'],['Fecha de salida / manifiesto','departure','date'],['Fecha de regreso','returnDate','date'],['Consignado a','consignee'],['Empresa de transporte','carrier'],['Unidad / N.º interno','unit'],['Dominio / patente','plate']];}
function busLegalCard(t){return '<section class="card" style="margin-bottom:20px"><div class="card-header"><h2>Datos del transporte · Manifiesto</h2>'+button('Editar cabecera','bus-legal')+'</div><div class="form-grid">'+legalFields().map(([label,key,type])=>'<div><small>'+esc(label)+'</small><p style="white-space:pre-wrap;overflow-wrap:anywhere">'+esc(t[key]?(type==='date'?dateText(t[key]):t[key]):'Sin completar')+'</p></div>').join('')+'</div></section>';}
function editBusLegal(){const t=trip();modal('Cabecera del manifiesto','<form id="bus-legal-form"><div class="form-grid">'+legalFields().map(([label,key,type])=>key==='route'?'<label class="field span2">Ruta<textarea name="route" rows="3">'+esc(t.route)+'</textarea></label>':field(label,key,t[key],type||'text')).join('')+'</div><div class="modal-actions">'+button('Cancelar','close')+'<button class="primary" type="submit">Guardar cabecera</button></div></form>');$('#bus-legal-form').onsubmit=async e=>{e.preventDefault();const fields=Object.fromEntries([...new FormData(e.target)].map(([k,v])=>[k,String(v).trim()]));const saved=await mutate(()=>{const draft={...t,...fields};C.validateTrip(draft);Object.assign(t,draft);});if(saved)closeModal();};}

document.addEventListener('click',e=>{const target=e.target.closest('[data-action],[data-view]'),action=target?.dataset.action;if(action==='zoom-out')applyReportZoom(reportZoom-.1);if(action==='zoom-in')applyReportZoom(reportZoom+.1);if(action==='zoom-fit')fitReportWidth();if(action==='goto-documents'||target?.dataset.view)$('#main').classList.remove('document-view');});
